// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdConfigName 是按仓库覆盖阈值的配置文件位置（相对仓库根）。
// 见 config/README.md。
const thresholdConfigName = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值来自 config/thresholds.json；文件里没有这个仓库，或者文件缺失、读不出来、
// 内容不是 JSON 对象时，回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, ok := loadThresholds()
	if !ok {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

// loadThresholds 读取按仓库覆盖的阈值。ok 为 false 表示配置缺失、读不出来或不是
// JSON 对象——三种情况一律让所有仓库回退到 DefaultLowStockThreshold。
func loadThresholds() (map[string]int, bool) {
	path, err := findThresholdConfig()
	if err != nil {
		return nil, false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, false
	}
	if thresholds == nil {
		return nil, false
	}
	return thresholds, true
}

// findThresholdConfig 找到 config/thresholds.json。它从工作目录逐级向上找，
// 这样无论服务从仓库根运行，还是测试从包目录运行，都能读到同一份配置。
func findThresholdConfig() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		path := filepath.Join(dir, thresholdConfigName)
		if info, err := os.Stat(path); err == nil && !info.IsDir() {
			return path, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", os.ErrNotExist
		}
		dir = parent
	}
}
```

