package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// writeThresholdConfig 在一个临时目录里放好 config/thresholds.json，并把工作目录
// 切过去，用来验证 LowStockThreshold 的读取与回退行为。
func writeThresholdConfig(t *testing.T, content string) {
	t.Helper()
	dir := t.TempDir()
	if err := os.MkdirAll(filepath.Join(dir, "config"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "config", "thresholds.json"), []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	t.Chdir(dir)
}

func TestLowStockThresholdUsesConfiguredValue(t *testing.T) {
	writeThresholdConfig(t, `{"beijing": 10}`)

	if got := LowStockThreshold("beijing"); got != 10 {
		t.Fatalf("LowStockThreshold(%q) = %d, 期望配置值 10", "beijing", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("LowStockThreshold(%q) = %d, 期望回退默认值 %d",
			"chengdu", got, DefaultLowStockThreshold)
	}
}

func TestLowStockThresholdFallsBackWhenConfigMissing(t *testing.T) {
	t.Chdir(t.TempDir())

	if got := LowStockThreshold("beijing"); got != DefaultLowStockThreshold {
		t.Fatalf("文件缺失时应回退默认值，得到 %d", got)
	}
}

func TestLowStockThresholdFallsBackOnInvalidConfig(t *testing.T) {
	cases := map[string]string{
		"不是合法 JSON": `{`,
		"不是 JSON 对象": `[1, 2]`,
		"是 JSON null":  `null`,
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			writeThresholdConfig(t, content)
			if got := LowStockThreshold("beijing"); got != DefaultLowStockThreshold {
				t.Fatalf("配置无效时应回退默认值，得到 %d", got)
			}
		})
	}
}

func TestLowStockThresholdFallsBackWhenConfigUnreadable(t *testing.T) {
	dir := t.TempDir()
	// 用同名目录占住路径：os.ReadFile 读目录会失败，模拟"读不出来"。
	if err := os.MkdirAll(filepath.Join(dir, "config", "thresholds.json"), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Chdir(dir)

	if got := LowStockThreshold("beijing"); got != DefaultLowStockThreshold {
		t.Fatalf("文件读不出来时应回退默认值，得到 %d", got)
	}
}

